def to_message(order) -> OrderMessage:          # invoked by the producer
    return OrderMessage(id=order.id,
                        customer_id=order.customer.id,   # reference -> id
                        total_minor=order.total.minor_units())

def from_message(m: OrderMessage) -> Order:      # invoked by the consumer
    return Order.rehydrate(m.id, m.customer_id, Money.minor(m.total_minor))
